# Parse good posture status from each note and compute longest streak
from datetime import datetime, timedelta

# Build a dict mapping date (as date object) to good_posture (True/False)
posture_by_date = {}
for note in habit_data:
    # Extract date from title: "Habit Tracking Log for YYYY-MM-DD"
    date_str = note['title'].replace('Habit Tracking Log for ', '')
    date_obj = datetime.strptime(date_str, '%Y-%m-%d').date()
    # Extract practiced_good_posture value from content
    content = note['content']
    for line in content.split('\n'):
        if line.strip().startswith('practiced_good_posture:'):
            value = line.split(':')[1].strip().lower()
            posture_by_date[date_obj] = (value == 'yes')
            break

# Sort dates
sorted_dates = sorted(posture_by_date.keys())
print("Dates and posture status:")
for d in sorted_dates:
    print(d, posture_by_date[d])

# Compute longest streak of consecutive days with good posture = True
max_streak = 0
current_streak = 0
prev_date = None
for d in sorted_dates:
    if posture_by_date[d]:
        if prev_date is not None and (d - prev_date).days == 1:
            current_streak += 1
        else:
            current_streak = 1
        if current_streak > max_streak:
            max_streak = current_streak
    else:
        current_streak = 0
    prev_date = d

print("Longest streak:", max_streak)

